// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address constant DEPOSITOR = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 seq_,
        bytes32 batcher_,
        uint256 overhead_,
        uint256 scalar_
    ) public {
        vm.startPrank(DEPOSITOR);
        c.setL1BlockValues(number_, timestamp_, basefee_, hash_, seq_, batcher_, overhead_, scalar_);
        vm.stopPrank();
        assertTrue(c.number() == number_, "number must equal the value passed to setL1BlockValues");
    }
}
